use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};

fn trace(seed: u64) -> Value {
    let names = vec!["a".into(), "b".into(), "c".into()];
    let policy = links::Policy {
        latency_ns: 100,
        jitter_ns: 50,
        loss_ppm: 500_000,
    };
    let mut links = links::Links::new(seed, &names, policy, BTreeMap::new()).unwrap();
    let mut outcomes = Vec::new();
    for send in 0..128 {
        if send == 20 {
            links
                .shape(1, "shape".into(), BTreeSet::from([(0, 1)]), policy)
                .unwrap();
        }
        if send == 80 {
            links.heal("shape");
        }
        if send % 7 == 0 {
            links.selected_drop(0, 1);
        }
        outcomes.push(format!("{:?}", links.decide(0, 1, send, send % 11 == 0)));
        links.decide(1, 0, send, false);
    }
    let mut witness = Sha256::new();
    links.witness(&mut witness);
    let mut disk =
        disk::Disk::new(None, Some(64))
            .unwrap()
            .with_fault_model(disk::DiskFaultModel {
                sector_bytes: 512,
                survival_probability: 0.5,
            });
    disk.write(0, &[b'A'; 64 * 512]).unwrap();
    disk.flush();
    disk.write(0, &[b'B'; 64 * 512]).unwrap();
    let (disk, lost) = disk.crashed_seeded(seed, "a", 2);
    let mut rng = rng::Rng::new(seed, "timer-jitter/a/0");
    let draws: Vec<_> = (0..16).map(|_| rng.next()).collect();
    json!({"seed":seed,"outcome_digest":format!("{:x}",Sha256::digest(serde_json::to_vec(&outcomes).unwrap())),"link_witness":format!("{:x}",witness.finalize()),
        "disk_digest":disk.digest(),"disk_lost":lost,"timer_draws":draws})
}

#[test]
fn no_checkpoint_streams_results_and_witnesses_equal_main() {
    let expected: Value =
        serde_json::from_str(include_str!("fixtures/checkpoint-feature-off-main.json")).unwrap();
    let observed = json!([0, 1, 2, 1009, u64::MAX].map(trace));
    assert_eq!(observed, expected);
}
